from pathlib import Path
from html import escape
import json

ROOT=Path(__file__).resolve().parent
interactions=json.loads((ROOT/'interaction-results.json').read_text(encoding='utf-8'))
v2_path=ROOT/'constellation-v2-results.json'
if v2_path.exists():
    v2=json.loads(v2_path.read_text(encoding='utf-8'))
    interactions=[r for r in interactions if r['name'].startswith(('01 ', '02 '))]+v2['results']
passed=sum(r['status']=='pass' for r in interactions)
rows=''.join('<tr><td>'+escape(r['name'])+'</td><td class="ok">'+escape(r['status'])+'</td></tr>' for r in interactions)
# Each card has one image link and one independent mobile link; no nested anchors.
cards=''.join(f'<article class="card"><a href="{n}-desktop.png"><img src="{n}-desktop.png" alt="{name}, настольный экран"></a><strong>{name}</strong><span><a href="{n}-desktop.png">1440 px</a> · <a href="{n}-mobile.png">390 px</a> · <a href="{n}-approval.png">Согласование</a></span></article>' for n,name in [('01','Observatory'),('02','Atelier'),('03','Constellation')])
html='''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Проверка проектного пакета — R&D Laboratory</title><style>
*{box-sizing:border-box}body{margin:0;background:#f5f7f3;color:#1e3134;font:15px/1.7 "Segoe UI",Arial,sans-serif}main{max-width:1160px;padding:48px 32px;margin:auto}a{color:#16787a}header{display:flex;gap:20px;justify-content:space-between;border-bottom:1px solid #d9e2dc;padding-bottom:25px}.eyebrow{font:11px Consolas,monospace;letter-spacing:1.5px;color:#44716b;text-transform:uppercase}h1{font-size:44px;line-height:1.12;letter-spacing:-1.5px;font-weight:550;margin:42px 0 23px}h2{font-size:26px;font-weight:550;margin-top:38px}.lead{font-size:18px;max-width:820px;color:#56716f}.stats{display:flex;gap:36px;flex-wrap:wrap;margin:35px 0;padding:22px 0;border-block:1px solid #d9e2dc}.stats strong{font-size:34px;font-weight:500;display:block}.stats span{font-size:12px;color:#52726f}.cards{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.card{border:1px solid #d6e0da;border-radius:9px;overflow:hidden;background:white}.card img{width:100%;display:block}.card strong,.card span{display:block;margin:12px 16px}.card span{font-size:12px}.table{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}td,th{padding:11px 15px;text-align:left;border-bottom:1px solid #d9e2dc}.ok{color:#168166}.note{border-left:3px solid #1a8886;padding:18px 22px;background:#e8f0e9}.links{display:flex;gap:20px;flex-wrap:wrap;font-size:13px}footer{font-size:12px;color:#627572;border-top:1px solid #d9e2dc;margin-top:40px;padding-top:20px}@media(max-width:700px){main{padding:25px 20px}.cards{grid-template-columns:1fr}h1{font-size:35px}header{flex-wrap:wrap}.stats{gap:22px}td{font-size:12px;overflow-wrap:anywhere}}a:focus-visible{outline:3px solid #31959a;outline-offset:4px}
</style><body><main><header><a href="../index.html">← R&D Laboratory</a><span class="eyebrow">Verification · 07.10.2026</span></header><h1>Проверено на готовых<br>HTML-артефактах.</h1><p class="lead">Браузерная проверка макетов, документов и взаимодействий. Результаты относятся к этому проектному пакету.</p>'''
html+=f'<div class="stats"><div><strong>{passed}/{len(interactions)}</strong><span>интерактивных проверок</span></div><div><strong>390 / 1440</strong><span>ширина проверенных экранов, px</span></div><div><strong>0</strong><span>ошибок JavaScript на проверенных страницах</span></div></div>'
html+='<h2>Визуальные снимки</h2><div class="cards">'+cards+'</div>'
html+='<h2>Охват</h2><p>Первый проход проверял три исходные концепции и документы. Обновлённый Constellation v2 проверяется отдельно в новом изолированном браузерном контексте: HTML подставляется как тестовый документ, все сетевые обращения блокируются, профиль и открытые вкладки пользователя не используются. Проверены отсутствие горизонтального переполнения страницы, загрузка локальных изображений, видимые пометки о синтетических данных, открытие и закрытие C4-схем и изменение масштаба. Дизайны осмотрены на настольных и мобильных снимках.</p><p>JSON Schema и пример плана прошли проверку Draft 2020-12. Локальные ссылки, якоря и идентификаторы проверены отдельно. Встроенные скрипты проходят проверку синтаксиса; графики и общие демопоказатели сверены между тремя вариантами.</p><div class="links"><a href="browser-discovery.json">UI-проверка первой итерации</a><a href="docs-results.json">Проверка документов</a><a href="interaction-results.json">Сценарии первой итерации</a><a href="constellation-v2-results.json">Constellation v2: текущая проверка</a><a href="../docs/constellation-ux-review.html">Покрытие функций v2</a><a href="package-results.json">Ссылки и JSON Schema</a></div>'
html+='<p>План альфы v1.1 и TASK-001 дополнительно проверены на 390 и 1440 px: <a href="alpha-plan-results.json">результаты проверки документов</a>. Проверки проектных материалов не являются приёмкой реализации продукта.</p>'
html+='<h2>Интерактивные сценарии</h2><div class="table"><table><thead><tr><th>Проверка</th><th>Результат</th></tr></thead><tbody>'+rows+'</tbody></table></div><h2>Границы проверки</h2><p class="note">Это прототипы интерфейса и проект архитектуры. Здесь не проверялись реальные провайдерские вызовы, производительность backend, изоляция исполнения или восстановление production-системы: такого backend в комплекте ещё нет. Приёмочные проверки будущей реализации перечислены в <a href="../docs/implementation-plan.html">плане</a>. Полный аудит доступности со screen reader не проводился.</p><footer>Откройте index.html после распаковки всего архива. Для готовых страниц не нужны установка пакетов, ключи API или подключение к интернету.</footer></main></body></html>'
(ROOT/'verification.html').write_text(html,encoding='utf-8')
print(f'QA report generated: {passed}/{len(interactions)} interaction checks passed.')
